SELECT COUNT(t_apply_bidding.id)
FROM t_apply_bidding
WHERE t_apply_bidding.tender_number = #{tenderNumber}
  AND t_apply_bidding.quotation_time >= #{signUpTime}
  AND t_apply_bidding.quotation_time <= #{signEndTime}

SELECT t_apply_bidding.latest_quotation
FROM t_apply_bidding
WHERE t_apply_bidding.id = #{id}

SELECT t_apply_bidding.quantity
FROM t_apply_bidding
WHERE t_apply_bidding.id = #{id}

SELECT COUNT(t_apply_bidding.customer_id)
FROM t_apply_bidding
WHERE t_apply_bidding.tender_number = #{tenderNumber}
  AND t_apply_bidding.status = '已报名'
  AND t_apply_bidding.customer_ip = #{customerIp}

SELECT COUNT(t_apply_bidding.customer_id)
FROM t_apply_bidding
WHERE t_apply_bidding.tender_number = #{tenderNumber}
  AND t_apply_bidding.status = '已报名'
  AND t_apply_bidding.customer_id = #{customerId}
